window.RP_SESSION={"id":"S-96621bc6534e","messages":[{"id":"RP-II-0059310","time":"2026-03-12T19:26:00+09:00","room":"RP II","name":"핀 머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 안- 내면 진-거 가위-!! \"","characters":["P-87b04eb56606"]},{"id":"RP-II-0059311","time":"2026-03-12T19:26:00+09:00","room":"RP II","name":"핀 머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 바위-!!\"","characters":["P-87b04eb56606"]},{"id":"RP-II-0059312","time":"2026-03-12T19:27:00+09:00","room":"RP II","name":"핀 머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 보-옷!!! \"","characters":["P-87b04eb56606"]},{"id":"RP-II-0059313","time":"2026-03-12T19:27:00+09:00","room":"RP II","name":"핀 머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"🤛","characters":["P-87b04eb56606"]},{"id":"RP-II-0059314","time":"2026-03-12T19:28:00+09:00","room":"RP II","name":"핀 머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"당신을 무엇을 내셨습니까?","characters":["P-87b04eb56606"]},{"id":"RP-II-0059315","time":"2026-03-12T19:28:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"!d3","characters":["P-b3929f308454"]},{"id":"RP-II-0059316","time":"2026-03-12T19:28:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"결과 : [1]\n합계 : [1]","characters":[]},{"id":"RP-II-0059317","time":"2026-03-12T19:28:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"✂","characters":["P-b3929f308454"]},{"id":"RP-II-0059318","time":"2026-03-12T19:28:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 엣. \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059319","time":"2026-03-12T19:29:00+09:00","room":"RP II","name":"핀 머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 트핳핳핳핫핫-!!!! 이번주 똥간 담당은 203호로구만-!! \"","characters":["P-87b04eb56606"]},{"id":"RP-II-0059320","time":"2026-03-12T19:29:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 안돼!!!! \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059321","time":"2026-03-12T19:30:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 화장실... 더 편하게 관리할 수 없을까... \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059322","time":"2026-03-12T19:31:00+09:00","room":"RP II","name":"핀 머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 핳핳핳핫, 잘 부탁하네 꼬불스턴군. 이번주는 아카쿠군이 어딘가에서 고구마를 잔뜩 얻어왔다오. \"","characters":["P-87b04eb56606"]},{"id":"RP-II-0059323","time":"2026-03-12T19:31:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 고구마요? \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059324","time":"2026-03-12T19:32:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 어딘가에서? \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059325","time":"2026-03-12T19:32:00+09:00","room":"RP II","name":"핀 머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 그렇다네. 핫핳핫 \"","characters":["P-87b04eb56606"]},{"id":"RP-II-0059326","time":"2026-03-12T19:32:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 그 출처를 알 수 없었던 치즈들... 같은검까? \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059327","time":"2026-03-12T19:32:00+09:00","room":"RP II","name":"핀 머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 에헤~이 그럴리가. 그 고구마들은 진짜였네. \"","characters":["P-87b04eb56606"]},{"id":"RP-II-0059328","time":"2026-03-12T19:33:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 헤에, 아카쿠님의 고구마라... \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059329","time":"2026-03-12T19:33:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" ...별로 고구마를 좋아하실 관상은 아니신데? \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059330","time":"2026-03-12T19:34:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 어쩌다 얻었담까. 샀을 것 같진 않고. \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059331","time":"2026-03-12T19:37:00+09:00","room":"RP II","name":"핀 머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 글쎄, 본인이 마사지를 하고 돈 대신 받아온건 아니겠소? 아님 시장은 친한 상인에게 얻어왔다던지 말일세. 핳핳핫, 인심 좋은 상인들도 있으니까 말이야. \"","characters":["P-87b04eb56606"]},{"id":"RP-II-0059332","time":"2026-03-12T19:39:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 흠, 고구마를 잔뜩이라... \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059333","time":"2026-03-12T19:39:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" ... \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059334","time":"2026-03-12T19:40:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" ...왕창 심어서 왕창 팔면 돈이 좀 되려나? \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059335","time":"2026-03-12T19:44:00+09:00","room":"RP II","name":"핀 머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 핳핳핫, 적은 용돈 정도는 괜찮겠지만 그보다야 다 같이 나눠먹는게 낫지 않겠소? 농사가 그리 만만한건 아닐세 꼬마돌군. \"","characters":["P-87b04eb56606"]},{"id":"RP-II-0059336","time":"2026-03-12T19:44:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 하긴, 길드에 입도 많이 는 것 같던검다. \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059337","time":"2026-03-12T19:45:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 방은 안 모자란검까? \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059338","time":"2026-03-12T19:52:00+09:00","room":"RP II","name":"핀 머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 방은 괜찮다네. 그보다 꼬마돌군 식사는 하셨소? 저녁때가 지났는데... 자네가 식당에서 밥 먹는 모습을 잘 못본 것 같구먼.\n\n늘 방에서 뭔가 하는 것 같은데... 뭘 하며 시간을 보내십니까? \"","characters":["P-87b04eb56606"]},{"id":"RP-II-0059339","time":"2026-03-12T19:57:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 아, 밥은 적당히 먹었슴다. 채소에 빵이랑 계란 몇 알 싸놓고 배고프면 꺼내먹는검다. \n\n방에서 말임까? 마공학 도구를 만듬다. \n\n어떻게 하면 더 마법을 효율적으로 쓸 수 있을까. 삶이 편해질까. 같은... \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059340","time":"2026-03-12T19:58:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 의수의 시제품을 만든다거나, 사람의 노동력을 대체할 수 있는 장치를 주로 연구함다. \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059341","time":"2026-03-12T20:05:00+09:00","room":"RP II","name":"핀 머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 그렇군. 내게도 그런 친구가 있었네. 그는 농부였는데, 어떻게하면 사람들이 더 편하게 농삿일을 할 수 있을까 고민하던 친구였지. 하루는 그 녀석이 힘이 덜 드는 쟁기를 만들겠다며 마을 헛간에 있는 쟁기를 몽땅 어질러놨는데, 녀석. 마을 아낙들에게 뒤지게 두들겨 맞았었다네. 비 오는 날 먼지 나도록 말야. 트핳핳핫...\n\n그래도, 난 녀석이 늘 멋있다고 생각했었네. 언젠간 뜻하는 바를 이루지 않았을까- 하고 말일세. \"","characters":["P-87b04eb56606"]},{"id":"RP-II-0059342","time":"2026-03-12T20:15:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" ! \"\n\n그의 그런 이야기에 눈을 초롱이며 말했다.\n\n\" 역시 그런 실험정신이 필요한검다. 훌륭하신 분이라는 생각이 듬다. \n\n——아틔시가 하는 일도 별반 다를 것 없는 일이기도 함다. \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059343","time":"2026-03-12T20:16:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 좀 더 불편함을 해소할... \"\n\n\" 그나저나 뭔가, 머독님은 친구가 많은 것 같은검다? \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059344","time":"2026-03-12T20:22:00+09:00","room":"RP II","name":"핀 머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 으잉? 그런가? 난 그렇게 잘 못느끼겠는데... \n\n무튼 친구가 없다고 느낀 적도 없으니. 그렇겠구만. \"","characters":["P-87b04eb56606"]},{"id":"RP-II-0059345","time":"2026-03-12T20:23:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 아틔시 같은 경우엔... 몇년 전부터 기억이 없어서. \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059346","time":"2026-03-12T20:23:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 살던 마을에 몇몇 사람들과 길드원분들 말고는 아는 사람이 없는검다. \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059347","time":"2026-03-12T20:23:00+09:00","room":"RP II","name":"핀 머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 아트시? \"","characters":["P-87b04eb56606"]},{"id":"RP-II-0059348","time":"2026-03-12T20:25:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 아, 본인 얘기임다. \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059349","time":"2026-03-12T20:26:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 그 머냐... 가장 마지막 기억 속의 단어가 그거라. 좀 잊지 않으려다보니. \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059350","time":"2026-03-12T20:26:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" '나'보다 '아틔시'라는 명칭이 입에 붙어버린검다! \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059351","time":"2026-03-12T20:46:00+09:00","room":"RP II","name":"핀 머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 아틔시라... 희안한 단어로구만. 대체 그게 무슨 뜻인가? \"","characters":["P-87b04eb56606"]},{"id":"RP-II-0059352","time":"2026-03-12T20:46:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 그걸 알면... \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059353","time":"2026-03-12T20:46:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 기억을 안 잃었지 말임다? \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059354","time":"2026-03-12T20:47:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 저도 모름다! \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059355","time":"2026-03-12T20:49:00+09:00","room":"RP II","name":"핀 머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"탁...!\n\n머독이 제 손바닥을 반댓손날로 내려쳤다.\n\n\" ... 그렇다면....! 자네 기억을 찾으러 떠나 보는 것도 나쁘지 않겠군! 다 같이 말일세! \"","characters":["P-87b04eb56606"]},{"id":"RP-II-0059356","time":"2026-03-12T20:49:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 기억, 그쵸... 기억을 찾아보는... \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059357","time":"2026-03-12T20:49:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" ...다 같이? \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059358","time":"2026-03-12T20:51:00+09:00","room":"RP II","name":"핀 머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 그래! 다 같이-! \"","characters":["P-87b04eb56606"]},{"id":"RP-II-0059359","time":"2026-03-12T20:52:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 그건 뭔가 민폐를 끼치는 것 같은데... \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059360","time":"2026-03-12T20:54:00+09:00","room":"RP II","name":"핀 머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 그럴리가 있겠소이까 꼬불라면군? 궁금해서 하는 일일세. 꼬라군의 과거와 잊혀진 기억 탐사...!! 으흐흐 으흐, 그거야 말로, 모험 아니겠소이까!? \"","characters":["P-87b04eb56606"]},{"id":"RP-II-0059361","time":"2026-03-12T20:54:00+09:00","room":"RP II","name":"핀 머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 트핳핳핳핫-!! \"","characters":["P-87b04eb56606"]},{"id":"RP-II-0059362","time":"2026-03-12T20:54:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 오... \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059363","time":"2026-03-12T20:55:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" ...단서가 더 생기면 고려해보겠슴다. \"","characters":["P-b3929f308454"]},{"id":"RP-II-0059364","time":"2026-03-12T20:55:00+09:00","room":"RP II","name":"코블","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"그러고는 자리에서 일어났다.","characters":["P-b3929f308454"]},{"id":"RP-II-0059365","time":"2026-03-12T20:56:00+09:00","room":"RP II","name":"핀 머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 트핳핳핳핫-! 트하-핳핳핫핫핫-!! \"","characters":["P-87b04eb56606"]},{"id":"RP-II-0059366","time":"2026-03-12T20:56:00+09:00","room":"RP II","name":"핀 머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-87b04eb56606"]},{"id":"RP-II-0059367","time":"2026-03-12T20:56:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
